class Solution {
    public int[] decode(int[] encoded,int first){
        int[] answer=new int[encoded.length+1];
        answer[0]=first;
        for(int i=0;i<encoded.length;i++)answer[i+1]=answer[i]^encoded[i];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun decode(encoded:IntArray,first:Int):IntArray{
        val answer=IntArray(encoded.size+1);
        answer[0]=first;
        for(i in encoded.indices)answer[i+1]=answer[i] xor encoded[i];
        return answer
    }
}

